def forward(groups):
    date = groups[0]
    space = groups[1]
    time = groups[2]
    dt = datetime.strptime(date + time, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(space)]}

def inverse(record):
    micros = int(record['stored'][0])
    space_length = record['layout'][0]
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%y%m%d') + (' ' * space_length) + dt.strftime('%H%M%S')
